window.DATA_PART=window.DATA_PART||{};window.DATA_PART["gdm"]={"lectures":[{"id":"gdm-v1","nr":"1","title":"Modul 1: Grundzüge und Funktionen der Unternehmung","date":"2026-11-12","summary":["Ein <b class=\"term\">Unternehmen</b>: System, sozio, ökonomisch, planvoll, organisiert. Es erstellt Güter für Dritte.","<b class=\"term\">Wertkette</b>: fünf primäre Aktivitäten entlang des Produkts, vier unterstützende darüber.","Gutenberg: <b class=\"term\">Elementarfaktoren</b> führen aus. Leitung und Planung: <b class=\"term\">Dispositiver Faktor</b>.","Arbeitsteilung braucht Abstimmung: <b class=\"term\">Koordinationsproblem</b> (Nicht-Wissen), <b class=\"term\">Motivationsproblem</b> (Nicht-Wollen).","<b class=\"term\">Effizienz</b>: die Dinge richtig tun. <b class=\"term\">Effektivität</b>: die richtigen Dinge tun."],"formulas":[],"visuals":[{"title":"Wertkette","svg":"<svg viewBox=\"0 0 400 242\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"10\" y=\"20\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Unterstützende Aktivitäten (für alle Stufen)</text><rect x=\"10\" y=\"30\" width=\"330\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"currentColor\"/><text x=\"18\" y=\"45\" fill=\"currentColor\" font-size=\"11\">Infrastruktur: Leitung, Planung, Finanzen</text><rect x=\"10\" y=\"56\" width=\"330\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"currentColor\"/><text x=\"18\" y=\"71\" fill=\"currentColor\" font-size=\"11\">Personal</text><rect x=\"10\" y=\"82\" width=\"330\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"currentColor\"/><text x=\"18\" y=\"97\" fill=\"currentColor\" font-size=\"11\">Technologieentwicklung</text><rect x=\"10\" y=\"108\" width=\"330\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"currentColor\"/><text x=\"18\" y=\"123\" fill=\"currentColor\" font-size=\"11\">Beschaffung (Einkauf)</text><rect x=\"10.0\" y=\"140\" width=\"66.0\" height=\"72\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"43.0\" y=\"172\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Eingangs-</text><text x=\"43.0\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">logistik</text><rect x=\"76.0\" y=\"140\" width=\"66.0\" height=\"72\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"109.0\" y=\"172\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Produk-</text><text x=\"109.0\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">tion</text><rect x=\"142.0\" y=\"140\" width=\"66.0\" height=\"72\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"175.0\" y=\"172\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Ausgangs-</text><text x=\"175.0\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">logistik</text><rect x=\"208.0\" y=\"140\" width=\"66.0\" height=\"72\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"241.0\" y=\"172\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Marketing,</text><text x=\"241.0\" y=\"186\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Vertrieb</text><rect x=\"274.0\" y=\"140\" width=\"66.0\" height=\"72\" fill=\"var(--acc-soft)\" stroke=\"currentColor\"/><text x=\"307.0\" y=\"180\" fill=\"currentColor\" font-size=\"11\" text-anchor=\"middle\">Service</text><polygon points=\"340,30 388,121 340,212\" fill=\"var(--acc)\" stroke=\"currentColor\"/><text x=\"344\" y=\"125\" fill=\"currentColor\" font-size=\"11\" font-weight=\"700\">Wert</text><text x=\"10\" y=\"232\" fill=\"currentColor\" font-size=\"12\" font-weight=\"700\">Primäre Aktivitäten (Weg des Produkts →)</text></svg>","caption":"Unten fünf primäre Aktivitäten entlang des Produkts, darüber vier unterstützende für alle Stufen. Zusammen schaffen sie Wert für den Kunden."}],"examples":[{"title":"Zwei Maurerkolonnen: effizient oder effektiv?","steps":["Ziel für heute: 40 m² Wand.","Kolonne A: 4 Leute × 8 h = 32 h, schafft 40 m². Effizienz: 40 : 32 = 1,25 m² je Stunde.","Kolonne B: 3 Leute × 8 h = 24 h, schafft 33 m². Effizienz: 33 : 24 = 1,375 m² je Stunde.","B ist effizienter (mehr m² je Stunde), aber nicht effektiv: 33 &lt; 40 m².","A ist effektiv (Ziel erreicht), aber weniger effizient."]}],"terms":[{"t":"Unternehmen","sym":"","d":"Sozio-ökonomisches System, das als planvoll organisierte Wirtschaftseinheit Güter und Dienstleistungen erstellt und an Dritte verwertet.","ex":"Ein Fertigteilwerk: 80 Beschäftigte gießen nach Plan 1.200 Deckenplatten im Quartal und verkaufen sie an Baufirmen.","vs":"Unternehmen ≠ privater Haushalt: Ein Haushalt stellt nichts her, um es an Dritte zu verkaufen.","topic":"gdm-m1"},{"t":"Wertkette","sym":"","d":"Zerlegt ein Unternehmen in Aktivitäten, die Wert schaffen. Fünf primäre folgen dem Weg des Produkts, vier unterstützende tragen alle Stufen.","ex":"Fensterbauer: Profile annehmen, Fenster bauen, ausliefern, verkaufen, warten. Dazu Infrastruktur, Personal, Technologie, Beschaffung.","vs":"Wertkette ≠ Produktionsfaktoren: Gutenberg zählt auf, was hineingeht. Die Wertkette zeigt, was getan wird.","topic":"gdm-m1"},{"t":"Elementarfaktoren","sym":"","d":"Gutenbergs ausführende Faktoren: ausführende Arbeit, Betriebsmittel (werden genutzt) und Werkstoffe (gehen ins Produkt ein).","ex":"Baustelle: Maurer (Arbeit), Kran und Mischer (Betriebsmittel), Ziegel und Mörtel (Werkstoffe).","vs":"Elementarfaktoren ≠ dispositiver Faktor: Sie führen aus. Der dispositive Faktor plant und lenkt.","topic":"gdm-m1"},{"t":"Dispositiver Faktor","sym":"","d":"Gutenbergs leitender Faktor: Leitung, Planung, Organisation und Überwachung. Er kombiniert die Elementarfaktoren.","ex":"Die Bauleitung legt fest, wann welche Kolonne mit welchem Kran welche Decke betoniert.","vs":"Nicht jede Büroarbeit ist dispositiv: Wer nur Rechnungen abtippt, leistet ausführende Arbeit.","topic":"gdm-m1"},{"t":"Effizienz","sym":"","d":"„Die Dinge richtig tun“: Verhältnis von Ergebnis zu Mitteleinsatz.","ex":"33 m² Wand in 24 Arbeitsstunden: 33 : 24 = 1,375 m² je Stunde.","vs":"Effizienz ≠ Effektivität: Effizient arbeiten nützt nichts, wenn das Ziel verfehlt wird.","topic":"gdm-m1"},{"t":"Effektivität","sym":"","d":"„Die richtigen Dinge tun“: Wird das gesetzte Ziel erreicht?","ex":"Ziel 40 m² Wand heute, geschafft 40 m²: effektiv, egal wie viele Stunden es gekostet hat.","vs":"Effektivität ≠ Effizienz: Effektivität fragt nach dem Ziel, Effizienz nach dem Aufwand.","topic":"gdm-m1"},{"t":"Minimalprinzip","sym":"","d":"Das Ergebnis ist fest. Es soll mit möglichst wenig Mitteleinsatz erreicht werden.","ex":"Genau 500 m² Estrich verlegen und dafür das günstigste Material suchen.","vs":"Minimalprinzip ≠ Maximalprinzip: Dort sind die Mittel fest und das Ergebnis soll möglichst groß werden.","topic":"gdm-m1"},{"t":"Maximalprinzip","sym":"","d":"Die Mittel sind fest. Mit ihnen soll ein möglichst großes Ergebnis erreicht werden.","ex":"Mit einem Lkw und einem Arbeitstag möglichst viele Paletten Ziegel ausliefern.","vs":"Maximalprinzip ≠ Minimalprinzip: Dort ist das Ergebnis fest und die Mittel sollen möglichst klein werden.","topic":"gdm-m1"},{"t":"Optimumprinzip","sym":"","d":"Mittel und Ergebnis sind beide frei wählbar. Gesucht ist das beste Verhältnis von Ergebnis zu Mitteleinsatz.","ex":"Ein Werk wählt Stückzahl und Zahl der Schichten so, dass die Kosten je Platte am kleinsten sind.","vs":"„Maximales Ergebnis mit minimalen Mitteln“ ist kein Prinzip: Beides zugleich geht nicht.","topic":"gdm-m1"},{"t":"Koordinationsproblem","sym":"","d":"Teil des Organisationsproblems: Beteiligte wissen nicht genug voneinander (Nicht-Wissen).","ex":"Das Werk liefert die Platten am Montag, die Baustelle braucht sie erst am Mittwoch und hat keinen Lagerplatz.","vs":"Koordinationsproblem ≠ Motivationsproblem: Hier fehlt Wissen, nicht der Wille. Es hilft Information.","topic":"gdm-m1"},{"t":"Motivationsproblem","sym":"","d":"Teil des Organisationsproblems: Beteiligte haben eigene Interessen und handeln nicht im Sinne des Ganzen (Nicht-Wollen).","ex":"Ein Subunternehmer wird pro m² bezahlt. Darum arbeitet er schnell, aber ungenau.","vs":"Motivationsproblem ≠ Koordinationsproblem: Alle wissen Bescheid, mehr Information hilft nicht. Es helfen Anreize und Kontrolle.","topic":"gdm-m1"},{"t":"Transaktionskosten","sym":"","d":"Kosten für Information und Kommunikation, um Arbeitsteilung und Tausch vorzubereiten, durchzuführen und zu überwachen. Merkregel: alles, was nicht Produktionskosten sind.","ex":"Drei Gerüstbauer um Angebote bitten, den Vertrag verhandeln, den Aufbau abnehmen.","vs":"Transaktionskosten ≠ Produktionskosten: Stahl für das Gerüst und die Arbeitszeit beim Aufbau sind Produktionskosten.","topic":"gdm-m1"}],"story":[{"tip":"Modul 1 läuft als Video (Videos 1–3). Schau sie vor der Session am 12.11. an; das Online-Tutorium 1 fragt genau diesen Stoff ab."},{"h":"Was ist ein Unternehmen?"},{"p":"Nimm ein Fertigteilwerk am Stadtrand. 80 Leute gießen dort Deckenplatten und verkaufen sie an Baufirmen. Warum nennt man das ein <b class=\"term\">Unternehmen</b>? Die Definition besteht aus fünf Bausteinen. Jeder Baustein beantwortet eine eigene Frage."},{"p":"<table class=\"tt\"><tr><th>Baustein</th><th>heißt</th><th>im Fertigteilwerk</th></tr><tr><td>System</td><td>Teile mit Beziehungen, eingebettet in ein Umfeld</td><td>Halle, Kräne, Beschäftigte, Lieferanten, Kunden</td></tr><tr><td>sozio</td><td>Menschen arbeiten zusammen</td><td>Schichtleitung, Former, Fahrer</td></tr><tr><td>ökonomisch</td><td>es gilt das Wirtschaftlichkeitsprinzip</td><td>kein Beton wird verschwendet</td></tr><tr><td>planvoll</td><td>es gibt Ziele und einen Plan</td><td>1.200 Platten im Quartal</td></tr><tr><td>organisiert</td><td>Regeln, Weisungs- und Entscheidungsrechte</td><td>wer darf eine Charge freigeben?</td></tr></table>"},{"p":"Die Betriebswirtschaftslehre (BWL) ist eine Sozialwissenschaft. Sie hat zwei Aufgaben. Sie <i>erklärt</i>, warum Menschen und Organisationen sich so verhalten. Und sie <i>gestaltet</i>: Sie gibt Empfehlungen, was ein Unternehmen tun sollte. Dafür nutzt sie Modelle und prüft sie an Daten."},{"p":"Das Werk steht nicht allein. Auf dem Beschaffungsmarkt kauft es Arbeit, Betriebsmittel und Werkstoffe. Auf dem Absatzmarkt verkauft es an Unternehmen, Haushalte und die öffentliche Hand. Dazu kommen der Kapitalmarkt (Kapital gegen Zinsen oder Gewinn), der Staat (Recht, Steuern, Subventionen), die natürliche Umwelt (Ressourcen, Emissionen) und die Kultur."},{"tip":"Lerne die fünf Bausteine mit je einem eigenen Beispiel. Dann kannst du die Definition herleiten, statt sie auswendig aufzusagen."},{"h":"Die Wertkette: was im Unternehmen passiert"},{"p":"Die <b class=\"term\">Wertkette</b> nach Porter zerlegt ein Unternehmen in Aktivitäten. Unten laufen fünf primäre Aktivitäten. Sie folgen dem Weg des Produkts: Eingangslogistik, Produktion, Ausgangslogistik, Marketing und Vertrieb, Service. Darüber liegen vier unterstützende Aktivitäten: Infrastruktur, Personal, Technologieentwicklung und Beschaffung. Sie tragen alle fünf Stufen zugleich."},{"v":0},{"p":"Im Fertigteilwerk heißt das: Zement und Stahl annehmen und lagern (Eingangslogistik). Platten gießen (Produktion). Platten auf den Tieflader laden (Ausgangslogistik). Angebote an Baufirmen schicken (Marketing und Vertrieb). Risse nach dem Einbau prüfen (Service). Der Einkauf, der mit dem Zementlieferanten den Preis verhandelt, ist dagegen Beschaffung, also unterstützend. Die Kette ist eingebettet: Vor ihr liegen die Wertketten der Lieferanten, nach ihr die der Vertriebskanäle und Abnehmer."},{"tip":"Typischer Fehler: Beschaffung und Eingangslogistik verwechseln. Beschaffung heißt einkaufen (Lieferant wählen, Preis verhandeln). Eingangslogistik heißt die Ware annehmen, lagern und an die Produktion geben."},{"h":"Warum gibt es Unternehmen? Bedürfnisse und Produktionsfaktoren"},{"p":"Menschen haben Bedürfnisse. Die Maslow-Pyramide ordnet sie von unten nach oben: physiologische Bedürfnisse, Sicherheit, soziale Bedürfnisse, Geltung, Selbstverwirklichung. Die unteren drei heißen Defizitbedürfnisse, die oberen zwei Wachstumsbedürfnisse. Die Güter dafür sind knapp. Also muss jemand sie herstellen."},{"p":"Dazu kombiniert ein Unternehmen Produktionsfaktoren. Nach Gutenberg gibt es drei <b class=\"term\">Elementarfaktoren</b>: ausführende Arbeit, Betriebsmittel und Werkstoffe. Leitung, Planung, Organisation und Überwachung bilden einen vierten, leitenden Faktor (<b class=\"term\">Dispositiver Faktor</b>)."},{"p":"Warum diese Trennung? Ein Kran, 20 m³ Beton und vier Arbeiter ergeben noch keine Decke. Erst wenn jemand plant, wann der Kran wo steht und wer was tut, wird daraus eine Leistung. Genau das ist die Aufgabe des dispositiven Faktors: Er kombiniert die Elementarfaktoren."},{"tip":"Betriebsmittel bleiben erhalten und werden genutzt (Kran, Schalung). Werkstoffe gehen ins Produkt ein (Beton, Bewehrung)."},{"p":"Wie hängen Gutenberg und Porter zusammen? Beide schauen auf das ganze Unternehmen und trennen das Kerngeschäft von der Unterstützung: Elementarfaktoren entsprechen grob den primären Aktivitäten, der dispositive Faktor den unterstützenden. Der Unterschied ist die Blickrichtung. Gutenberg fragt nach dem, was hineingeht (Faktorsicht, Input). Porter fragt nach dem, was getan wird und herauskommt (Prozesssicht, Output)."},{"h":"Arbeitsteilung und das Organisationsproblem"},{"p":"Mittel sind knapp, und niemand kann alles. Darum teilen Menschen die Arbeit auf (Arbeitsteilung und Spezialisierung, nach Adam Smith). Wer immer dasselbe macht, lernt dazu, nutzt Spezialverfahren und ist schneller eingelernt. Das gilt für Personen, Abteilungen, Unternehmen und ganze Volkswirtschaften."},{"p":"Arbeitsteilung hat einen Preis. Zwischen Akteuren muss getauscht werden, im Unternehmen muss abgestimmt werden. Beides braucht Information, und die ist meist unvollständig. So entsteht das Organisationsproblem: die Aufgabe zerlegen, die Teile wieder zusammenfügen, die Menschen motivieren. Das <b class=\"term\">Koordinationsproblem</b> heißt Nicht-Wissen: Die Schalungskolonne weiß nicht, dass der Stahl einen Tag später kommt. Das <b class=\"term\">Motivationsproblem</b> heißt Nicht-Wollen: Die Kolonne weiß es, wird aber nach Stunden bezahlt und hat keinen Grund umzuplanen."},{"tip":"Frag bei jedem Fall: Fehlt Wissen (Koordination) oder fehlt der Wille (Motivation)? Gegen Nicht-Wissen hilft Information, gegen Nicht-Wollen helfen Anreize und Kontrolle."},{"h":"Wirtschaftlich handeln: Effizienz und Effektivität"},{"p":"Jedes Unternehmen verwandelt Input in Output. Input sind die Faktoren: Arbeitsstunden, Material, Maschinen. In der Transformation entsteht daraus der Output: Platten, Fenster, Gebäude. Wirtschaftlich handeln heißt, Input und Output in ein gutes Verhältnis zu bringen. Dafür gibt es drei Ausprägungen."},{"p":"<table class=\"tt\"><tr><th>Prinzip</th><th>fest</th><th>gesucht</th><th>Beispiel</th></tr><tr><td><b class=\"term\">Minimalprinzip</b></td><td>Output</td><td>möglichst wenig Input</td><td>500 m² Estrich, günstigstes Material</td></tr><tr><td><b class=\"term\">Maximalprinzip</b></td><td>Input</td><td>möglichst viel Output</td><td>1 Lkw, 1 Tag: möglichst viele Paletten</td></tr><tr><td><b class=\"term\">Optimumprinzip</b></td><td>nichts</td><td>bestes Verhältnis Output zu Input</td><td>Stückzahl und Schichten frei wählen</td></tr></table>"},{"p":"Zwei Begriffe musst du trennen. <b class=\"term\">Effizienz</b> heißt „die Dinge richtig tun“. Sie misst Output je Input. <b class=\"term\">Effektivität</b> heißt „die richtigen Dinge tun“. Sie fragt, ob das Ziel erreicht ist. Das Beispiel zeigt, dass beides auseinanderfallen kann."},{"ex":0},{"tip":"Typischer Fehler: „mit minimalem Einsatz den maximalen Ertrag“. Das geht nicht, eine Größe muss festliegen. Sonst wäre die Antwort immer: nichts einsetzen und unendlich viel herausholen."},{"p":"Wirtschaftlich handeln heißt nicht nur rechnen. Bei Corporate Social Responsibility (CSR) leisten Unternehmen soziale, ökologische und ökonomische Beiträge, die über das Gesetz hinausgehen. Die Felder sind Markt, Umwelt, Arbeitsplatz und Stakeholder."},{"h":"Selbermachen oder Fremdbeziehen?"},{"p":"Arbeitsteilung und Tausch kosten Information und Kommunikation. Diese Kosten heißen <b class=\"term\">Transaktionskosten</b> (Neue Institutionenökonomie nach Coase und Williamson). Merkregel: alles, was nicht Produktionskosten sind. Beispiele: Angebote einholen, einen Vertrag verhandeln, eine Lieferung prüfen."},{"p":"Daraus folgt eine Grundfrage. Soll das Werk die Bewehrungskörbe selbst biegen oder bei einem Biegebetrieb kaufen? Kauft es am Markt, kosten Suche, Verhandlung und Kontrolle. Macht es selbst, kosten Abstimmung und Motivation im eigenen Haus. Unternehmen und Markt sind also zwei Organisationsformen. Gewählt wird die Form mit den kleinsten Transaktionskosten."},{"h":"Information als Kern: Innovation"},{"p":"Für Schumpeter ist der Unternehmer der, der „neue Kombinationen“ durchsetzt. Das Neue verdrängt das Alte: schöpferische Zerstörung. Streamingdienste haben Teile der Medienindustrie verdrängt, Fahrdienst-Apps setzen das Taxi unter Druck. Grundlage ist ein Informationsvorsprung: Wer etwas zuerst weiß oder kann, gewinnt."},{"p":"Darum gibt es kein „optimales“ Unternehmen für immer. Wettbewerb, Informationstechnik und Wertewandel ändern laufend die Bedingungen. So entstehen neue Organisationsformen."}]}],"tasks":[{"id":"gdm-t1","topic":"gdm-m1","level":1,"type":"mc","diag":true,"src":"eigene (Typ wie Online-Tutorium 1, Aufgabe 4)","q":"Ein Fensterbauer stellt Kunststofffenster her. Welche Tätigkeit gehört in seiner Wertkette zu den <b>unterstützenden</b> Aktivitäten?","options":["Mit drei Profilherstellern über Preis und Lieferzeit verhandeln","Angelieferte Profile prüfen und ins Lager einräumen","Fertige Fenster auf den Lkw laden und zur Baustelle fahren","Ein klemmendes Fenster beim Kunden nachstellen"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Jede Tätigkeit einer der neun Aktivitäten der Wertkette zuordnen und die unterstützende finden.</p>\n<ol class=\"sol-steps\">\n<li>Die fünf primären Aktivitäten: Eingangslogistik, Produktion, Ausgangslogistik, Marketing und Vertrieb, Service.<span class=\"why\">Warum: Primär ist alles, was das Produkt selbst auf seinem Weg zum Kunden bewegt oder verändert.</span></li>\n<li>Profile prüfen und einlagern: <b>Eingangslogistik</b>, primär.<span class=\"why\">Warum: Die Ware ist schon da. Annehmen, lagern und an die Produktion geben gehört zum Weg des Produkts.</span></li>\n<li>Fenster laden und zur Baustelle fahren: <b>Ausgangslogistik</b>, primär.<span class=\"why\">Warum: Das fertige Produkt wird zum Kunden gebracht.</span></li>\n<li>Klemmendes Fenster nachstellen: <b>Service</b>, primär.<span class=\"why\">Warum: Service ist die letzte primäre Stufe: Er hält den Wert des Produkts nach dem Verkauf.</span></li>\n<li>Mit Profilherstellern verhandeln: <b>Beschaffung</b>, unterstützend.<span class=\"why\">Warum: Beschaffung ist der Einkaufsvorgang selbst: Lieferanten wählen, Preise und Termine aushandeln. Sie dient allen Stufen, nicht nur einer.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Frag bei jeder Tätigkeit: Fasst hier jemand das Produkt an oder bewegt es? Nur beim Verhandeln ist das nicht so.</p>\n<p class=\"merke\"><b>Merke:</b> Beschaffung (einkaufen) ist unterstützend. Eingangslogistik (annehmen und lagern) ist primär.</p>","short":"Verhandeln mit Profilherstellern = Beschaffung (unterstützend)"},{"id":"gdm-t2","topic":"gdm-m1","level":1,"type":"mc","diag":true,"src":"eigene (Typ wie Online-Tutorium 1, Aufgabe 3)","q":"Auf einer Baustelle wird eine Decke betoniert. Was ist nach Gutenberg der <b>dispositive Faktor</b>?","options":["Die Bauleitung legt fest, wann welche Kolonne mit welchem Kran betoniert, und kontrolliert den Fortschritt","Der Kranführer hebt den Betonkübel an die richtige Stelle","Die Betonpumpe","Der Frischbeton und die Bewehrung"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Die vier Möglichkeiten den Faktoren nach Gutenberg zuordnen.</p>\n<ol class=\"sol-steps\">\n<li>Elementarfaktoren: ausführende Arbeit, Betriebsmittel, Werkstoffe. Dispositiver Faktor: Leitung, Planung, Organisation, Überwachung.<span class=\"why\">Warum: Gutenberg trennt, wer etwas ausführt oder womit etwas gemacht wird, von dem, der das alles kombiniert.</span></li>\n<li>Kranführer: <b>ausführende Arbeit</b>.<span class=\"why\">Warum: Er arbeitet direkt am Produkt mit, plant aber nicht den Ablauf.</span></li>\n<li>Betonpumpe: <b>Betriebsmittel</b>.<span class=\"why\">Warum: Sie wird genutzt und bleibt danach erhalten.</span></li>\n<li>Frischbeton und Bewehrung: <b>Werkstoffe</b>.<span class=\"why\">Warum: Sie gehen in die Decke ein und sind danach Teil des Produkts.</span></li>\n<li>Bauleitung plant, teilt ein, kontrolliert: <b>dispositiver Faktor</b>.<span class=\"why\">Warum: Sie kombiniert die anderen drei Faktoren. Ohne sie stehen Kran, Beton und Leute nur herum.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Jede der vier Möglichkeiten passt zu genau einem Faktor: Arbeit, Betriebsmittel, Werkstoff, dispositiv. Keiner bleibt übrig.</p>\n<p class=\"merke\"><b>Merke:</b> Dispositiv = lenken (planen, organisieren, überwachen). Alles andere führt aus oder wird verbraucht.</p>","short":"Die Bauleitung (planen, einteilen, kontrollieren)"},{"id":"gdm-t3","topic":"gdm-m1","level":2,"type":"mc","diag":true,"src":"eigene (Typ wie Online-Tutorium 1, Aufgabe 1)","q":"Ein Fertigteilwerk hat für November ein festes Zementbudget von 60.000 €. Die Werksleitung will daraus so viele Treppenläufe wie möglich herstellen. Nach welchem Prinzip handelt sie?","options":["Maximalprinzip","Minimalprinzip","Optimumprinzip","Keinem: Mehr Stück bei gleichen Kosten ist Effektivität, nicht Wirtschaftlichkeit"],"correct":0,"a":"<p class=\"goal\"><b>Ziel:</b> Herausfinden, welche Größe festliegt und welche verbessert werden soll.</p>\n<ol class=\"sol-steps\">\n<li>Input = Zement für 60.000 €, Output = Zahl der Treppenläufe.<span class=\"why\">Warum: Jedes Prinzip vergleicht Input und Output. Darum zuerst beide benennen.</span></li>\n<li>Fest ist der Input (60.000 €). Gesucht ist möglichst viel Output.<span class=\"why\">Warum: „Festes Budget“ legt die Mittel fest. „So viele wie möglich“ heißt: Das Ergebnis soll wachsen.</span></li>\n<li>Input fest, Output maximal: <b>Maximalprinzip</b>.<span class=\"why\">Warum: Genau so ist das Maximalprinzip gebaut.</span></li>\n<li>Nicht Minimalprinzip: Dort wäre die Stückzahl fest und das Budget würde gesenkt.<span class=\"why\">Warum: Das ist die häufigste Verwechslung. Prüfe immer, was fest ist.</span></li>\n<li>Nicht Optimumprinzip und nicht „nur Effektivität“.<span class=\"why\">Warum: Beim Optimumprinzip ist nichts fest. Effektivität fragt nur, ob ein Ziel erreicht wird, nicht nach dem Verhältnis von Output zu Input.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Dreh den Fall um: Müsste das Werk genau 300 Treppenläufe liefern und das billigste Rezept suchen, wäre der Output fest. Das wäre das Minimalprinzip.</p>\n<p class=\"merke\"><b>Merke:</b> Erst fragen „Was ist fest?“. Input fest → Maximalprinzip. Output fest → Minimalprinzip. Nichts fest → Optimumprinzip.</p>","short":"Maximalprinzip (Input fest, Output maximal)"},{"id":"gdm-t4","topic":"gdm-m1","level":2,"type":"open","diag":true,"src":"eigene (Typ wie Online-Tutorium 1, Aufgabe 1)","q":"Ein Fensterbauer soll in zwei gleichen Wohnblöcken je 30 Fenster in einer Woche einbauen. Jeder Monteur arbeitet 40 h. Kolonne A (3 Monteure) baut 30 Fenster ein, Kolonne B (2 Monteure) baut 24 Fenster ein.<br/>a) Berechne für beide Kolonnen die Effizienz in Fenstern je Arbeitsstunde.<br/>b) Welche Kolonne ist effektiv?<br/>c) Wie viele Arbeitsstunden hätte B für 30 Fenster gebraucht, wenn sie gleich effizient weiterarbeitet? Was folgt daraus für die Leitung?","a":"<p class=\"goal\"><b>Ziel:</b> Effizienz (Output je Input) und Effektivität (Ziel erreicht?) getrennt prüfen.</p>\n<ol class=\"sol-steps\">\n<li>Input in Arbeitsstunden: A: 3 · 40 = 120 h. B: 2 · 40 = 80 h.<span class=\"why\">Warum: Effizienz vergleicht Ergebnis und Einsatz. Die Kolonnen sind verschieden groß, darum zählen die Stunden, nicht die Köpfe.</span></li>\n<li>a) A: 30 : 120 = <b>0,25</b> Fenster je Stunde (4 h je Fenster). B: 24 : 80 = <b>0,3</b> Fenster je Stunde (3 h 20 min je Fenster).<span class=\"why\">Warum: Mehr Output je Stunde heißt effizienter. B ist also effizienter.</span></li>\n<li>b) Ziel je Block: 30 Fenster. A: 30 = 30, <b>effektiv</b>. B: 24 &lt; 30, <b>nicht effektiv</b>.<span class=\"why\">Warum: Effektivität fragt nur, ob das Ziel erreicht ist. Wie viel Aufwand es war, spielt hier keine Rolle.</span></li>\n<li>c) B braucht für 30 Fenster 30 : 0,3 = <b>100 h</b>, also 20 h weniger als A.<span class=\"why\">Warum: Mit gleicher Effizienz wächst der Output im gleichen Verhältnis wie die Stunden.</span></li>\n<li>Folge: Die Arbeitsweise von B ist besser. Die Leitung sollte B mehr Kapazität geben (etwa einen dritten Monteur) und die Methode von B an A weitergeben.<span class=\"why\">Warum: Mit 3 Monteuren im Tempo von B wären es 3 · 40 · 0,3 = 36 Fenster pro Woche. Dann wäre B effizient <i>und</i> effektiv.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> 0,3 · 100 = 30 Fenster und 0,25 · 120 = 30 Fenster. Beide Wege führen zum Ziel, B braucht dafür 20 h weniger.</p>\n<p class=\"merke\"><b>Merke:</b> Effizienz = Output je Input („die Dinge richtig tun“). Effektivität = Ziel erreicht („die richtigen Dinge tun“). Beides kann auseinanderfallen.</p>","short":"A: 0,25 Fenster/h, effektiv · B: 0,3 Fenster/h, nicht effektiv · B bräuchte 100 h für 30 Fenster"},{"id":"gdm-t5","topic":"gdm-m1","level":3,"type":"open","diag":true,"src":"eigene (Typ wie Online-Tutorium 1, Aufgabe 2)","q":"Ein Fertigteilwerk kauft seine Bewehrungskörbe bei einem fremden Biegebetrieb. Zwei Dinge laufen schief: (1) Geänderte Bewehrungspläne erreichen den Biegebetrieb oft erst, wenn schon gebogen ist. (2) Der Biegebetrieb wird pro Tonne bezahlt und schiebt kleine, aufwendige Aufträge nach hinten. Die Leitung überlegt, eine eigene Biegerei aufzubauen.<br/>a) Erkläre, warum es arbeitsteilige Unternehmen wie Werk und Biegebetrieb überhaupt gibt.<br/>b) Ordne (1) und (2) dem Koordinations- oder dem Motivationsproblem zu und begründe.<br/>c) Welche Transaktionskosten fallen bei Fremdbezug an, welche bei Eigenfertigung? Nach welchem Maßstab sollte die Leitung entscheiden?","a":"<p class=\"goal\"><b>Ziel:</b> Die Kette Knappheit → Arbeitsteilung → Organisationsproblem am Fall zeigen und die Entscheidung über Transaktionskosten begründen.</p>\n<ol class=\"sol-steps\">\n<li>a) Bedürfnisse sind groß, Mittel und Fähigkeiten knapp. Darum spezialisieren sich Werk (Platten) und Biegebetrieb (Körbe).<span class=\"why\">Warum: Wer sich spezialisiert, lernt dazu, nutzt Spezialmaschinen und arbeitet schneller. Das spart knappe Mittel.</span></li>\n<li>Spezialisierung erzwingt Tausch zwischen beiden und Abstimmung im Werk. Beides braucht Information, und die ist unvollständig.<span class=\"why\">Warum: Darum entsteht das Organisationsproblem: zerlegen, zusammenfügen, motivieren.</span></li>\n<li>b) (1) ist ein <b>Koordinationsproblem</b> (Nicht-Wissen).<span class=\"why\">Warum: Der Biegebetrieb würde richtig biegen, er weiß nur nichts von der Änderung. Es fehlt Information, nicht der Wille.</span></li>\n<li>(2) ist ein <b>Motivationsproblem</b> (Nicht-Wollen).<span class=\"why\">Warum: Der Biegebetrieb kennt die Aufträge. Er hat aber eigene Interessen: Pro Tonne lohnen sich große, einfache Aufträge mehr.</span></li>\n<li>c) Fremdbezug: Lieferanten suchen, Angebote vergleichen, Vertrag verhandeln, Lieferung prüfen, bei Fehlern nachverhandeln.<span class=\"why\">Warum: Das sind Kosten für Information und Kommunikation rund um den Tausch am Markt.</span></li>\n<li>Eigenfertigung: Pläne intern weitergeben, die neue Abteilung einteilen, anleiten und überwachen, Anreize für die eigenen Leute setzen.<span class=\"why\">Warum: Das Organisationsproblem verschwindet nicht, es wandert ins Werk. Auch eigene Leute können Wissen fehlen oder Lust.</span></li>\n<li>Maßstab: die Organisationsform (Markt oder Unternehmen) mit den <b>kleinsten Transaktionskosten</b>. Stahl, Maschinen und Arbeitszeit beim Biegen sind Produktionskosten und kommen getrennt in den Vergleich.<span class=\"why\">Warum: Transaktionskosten sind alles, was nicht Produktionskosten ist. Wer beides vermischt, vergleicht falsch.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Gegenprobe zu b): Würde mehr Information (gemeinsame Planliste) Problem (2) lösen? Nein, der Anreiz pro Tonne bliebe. Also ist (2) wirklich Motivation, (1) wirklich Koordination.</p>\n<p class=\"merke\"><b>Merke:</b> Nicht-Wissen → Koordination → Information hilft. Nicht-Wollen → Motivation → Anreize helfen. Ob Markt oder eigenes Haus, entscheiden die Transaktionskosten. Oft gibt es einen Mittelweg: Fremdbezug behalten, aber Pläne digital teilen (Koordination) und pro Auftrag mit Terminbonus bezahlen (Motivation).</p>","short":"(1) Koordination, (2) Motivation · Entscheidung: Form mit den kleinsten Transaktionskosten"},{"id":"gdm-t6","topic":"gdm-m1","level":3,"type":"open","diag":false,"src":"eigene (Typ wie Online-Tutorium 1, Aufgaben 5 und 6)","q":"Zwei Fensterbauer in derselben Stadt haben fast die gleiche Wertkette: gleiche Maschinen, gleiche Lieferanten, gleich viele Monteure. Trotzdem verdient der eine deutlich mehr.<br/>a) Vergleiche Gutenbergs Produktionsfaktoren mit Porters Wertkette: zwei Gemeinsamkeiten, zwei Unterschiede.<br/>b) Wie können zwei gleich aufgebaute Wertketten unterschiedlich erfolgreich sein?<br/>c) Was folgt daraus für die Unternehmensleitung?","a":"<p class=\"goal\"><b>Ziel:</b> Beide Modelle sauber vergleichen und daraus erklären, woher ein Wettbewerbsvorteil kommt.</p>\n<ol class=\"sol-steps\">\n<li>a) Gemeinsam 1: Beide beschreiben, wie ein Unternehmen Leistungen erstellt.<span class=\"why\">Warum: Beide sind Modelle der Leistungserstellung. Sie schauen nur aus verschiedenen Richtungen darauf.</span></li>\n<li>Gemeinsam 2: Beide trennen Ausführen von Lenken. Bei Gutenberg sind das Elementarfaktoren und dispositiver Faktor, bei Porter primäre und unterstützende Aktivitäten (mit Leitung in der Infrastruktur).<span class=\"why\">Warum: Ohne eine lenkende Ebene wird aus einzelnen Teilen keine Leistung.</span></li>\n<li>Unterschied 1: Gutenberg fragt, <i>was hineingeht</i> (Faktoren, Input). Porter fragt, <i>was getan wird</i> (Aktivitäten, Prozess).<span class=\"why\">Warum: Ein Kran ist bei Gutenberg ein Betriebsmittel. Bei Porter zählt, in welcher Aktivität er Wert schafft.</span></li>\n<li>Unterschied 2: Porter schaut auf den Wert für den Kunden und bettet die Kette zwischen Lieferanten und Abnehmer. Gutenberg bleibt bei der Kombination im Unternehmen.<span class=\"why\">Warum: Darum eignet sich die Wertkette besser, um Wettbewerb zu erklären.</span></li>\n<li>b) Die Wertkette zeigt nur, <i>welche</i> Aktivitäten es gibt, nicht <i>wie gut</i> sie laufen und zusammenpassen. Der Unterschied liegt darin, wie gut ein Betrieb das Organisationsproblem löst: Wissen alle an den Schnittstellen, was zu tun ist (Koordination), und wollen sie es auch (Motivation)?<span class=\"why\">Warum: Beispiel: Gleiche Monteure, aber bei einem kommen geänderte Maße sofort auf der Baustelle an, und die Kolonne hat einen Terminbonus. Sie schafft zwei Baustellen am Tag. Das ist ein Wettbewerbsvorteil.</span></li>\n<li>c) Die Leitung sorgt für eine klare Struktur, eindeutige Kommunikationswege, eine konkrete Aufgabenverteilung und eine Führung, die motiviert. Außerdem prüft sie jede Aktivität: Wo sind wir besser oder günstiger als andere?<span class=\"why\">Warum: Das ist genau die Aufgabe des dispositiven Faktors: kombinieren, planen, überwachen. Gleiche Teile, besser kombiniert, ergeben mehr Wert.</span></li>\n</ol>\n<p class=\"check\"><b>Probe:</b> Prüfe b) mit der Frage: Könnte der schwächere Betrieb den Vorsprung einfach kopieren, indem er die gleiche Maschine kauft? Nein, er hat sie ja schon. Der Unterschied liegt also in der Ausführung und Abstimmung.</p>\n<p class=\"merke\"><b>Merke:</b> Gutenberg = Faktorsicht (Input), Porter = Prozesssicht (Aktivitäten, Output). Unternehmenserfolg = wie gut das Organisationsproblem gelöst wird, nicht welche Aktivitäten es gibt.</p>","short":"Gutenberg: Faktorsicht (Input), Porter: Prozesssicht · Erfolg: Organisationsproblem (Koordination, Motivation) besser lösen"}],"formulas":[]};